package com.renthouse.review;import com.renthouse.common.api.*;import jakarta.validation.*;import jakarta.validation.constraints.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/v1")public class ReviewController{private final ReviewService s;public ReviewController(ReviewService s){this.s=s;}@PostMapping("/tenant/contracts/{contractId}/reviews")ApiResponse<Void>create(@PathVariable long contractId,@RequestBody @Valid Create r){s.create(contractId,r.rating(),r.content());return ApiResponse.ok();}@PostMapping("/landlord/reviews/{id}/reply")ApiResponse<Void>reply(@PathVariable long id,@RequestBody @Valid Reply r){s.reply(id,r.content());return ApiResponse.ok();}public record Create(@Min(1)@Max(5)int rating,@Size(max=1000)String content){}public record Reply(@NotBlank@Size(max=1000)String content){}}
